// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler, ERC20, CoolerFactory} from "../src/Cooler.sol";

contract InvMutTest is Test {
    CoolerFactory factory;
    function setUp() public { factory = new CoolerFactory(); }

    function testFuzz_property(
        address owner0,
        address lender1,
        address attacker,
        address to_,
        uint256 amount,
        uint256 interest,
        uint256 ltc,
        uint256 duration
    ) public {
        vm.assume(owner0 != address(0) && lender1 != address(0) && attacker != address(0) && to_ != address(0));
        vm.assume(owner0 != lender1 && owner0 != attacker && lender1 != attacker);
        amount = bound(amount, 1e18, 1e24);
        ltc = bound(ltc, 1e18, 1e18);
        interest = bound(interest, 0, 1e17);
        duration = bound(duration, 1 days, 365 days);

        MockERC20 tokA = new MockERC20();
        MockERC20 tokB = new MockERC20();

        vm.prank(owner0);
        address coolerAddr = factory.generateCooler(tokA, tokB);
        Cooler c = Cooler(coolerAddr);
        require(c.owner() == owner0, "owner mismatch");

        vm.startPrank(owner0);
        c.requestLoan(amount, interest, ltc, duration);
        vm.stopPrank();

        uint256 debtAmt = amount + c.interestFor(amount, interest, duration);
        tokB.mint(lender1, debtAmt);
        vm.startPrank(lender1);
        tokB.approve(coolerAddr, debtAmt);
        c.clearRequest(0, false, false);
        // lender1 approves attacker, attacker takes over the loan; approvals[0] is reset to 0
        c.approveTransfer(attacker, 0);
        vm.stopPrank();
        vm.prank(attacker);
        c.transferOwnership(0);
        require(c.getLoan(0).lender == attacker, "lender mismatch");

        // after the ownership transfer, approvals[0] == 0 and the new lender is attacker;
        // the cooler owner (owner0) is NOT the lender, so approveTransfer must revert
        bool ok;
        vm.prank(owner0);
        try c.approveTransfer(to_, 0) { ok = true; } catch { ok = false; }

        assertTrue(!ok, "non-lender must not be able to set approvals after ownership transfer");
    }
}

contract MockERC20 is ERC20 {
    constructor() ERC20("mock", "MK", 18) {}
    function mint(address to, uint256 amt) external { _mint(to, amt); }
    function transferFrom(address from, address to, uint256 amt) public override returns (bool) { return true; }
    function transfer(address to, uint256 amt) public override returns (bool) { return true; }
}
